.manageGradientBtn {
  background: linear-gradient(90deg, #43e97b 0%, #38f9d7 100%);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 0.5em 1.25em;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 1px 4px 0 rgba(60, 120, 80, 0.10);
  outline: none;
  transition: background 0.2s, box-shadow 0.2s, transform 0.1s, color 0.2s;
}

.manageGradientBtn:hover,
.manageGradientBtn:focus {
  background: linear-gradient(90deg, #38f9d7 0%, #43e97b 100%);
  box-shadow: 0 2px 7px 0 rgba(60, 120, 80, 0.18);
  color: #fafafa;
  transform: translateY(-1px) scale(1.02);
}

.manageGradientBtn:active {
  background: linear-gradient(90deg, #3ecf8e 0%, #38f9d7 100%);
  color: #eaffec;
  transform: scale(0.98);
}

